import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useQuery } from '@tanstack/react-query';
import axiosInstance from '../core/api/axiosConfig';
import { Box, Typography, TextField, Tabs, Tab, Paper, List, ListItem, ListItemText, CircularProgress, Chip } from '@mui/material';
import SearchIcon from '@mui/icons-material/Search';

const AdvancedSearchPage = () => {
  const { t } = useTranslation();
  const [tab, setTab] = useState(0);
  const [query, setQuery] = useState('');
  const [debouncedQuery, setDebouncedQuery] = React.useState('');

  React.useEffect(() => {
    const timer = setTimeout(() => setDebouncedQuery(query), 400);
    return () => clearTimeout(timer);
  }, [query]);

  const { data, isLoading } = useQuery({
    queryKey: ['search', debouncedQuery, tab],
    queryFn: () => axiosInstance.post('/search/', { query: debouncedQuery, type: tab === 0 ? 'employees' : 'documents' }).then(r => r.data),
    enabled: debouncedQuery.length >= 2,
  });

  return (
    <Box>
      <Typography variant="h4" gutterBottom>{t('search.title')}</Typography>
      <TextField fullWidth size="medium" placeholder={t('search.placeholder')}
        value={query} onChange={e => setQuery(e.target.value)}
        InputProps={{ startAdornment: <SearchIcon sx={{ mr: 1, color: 'gray' }} /> }}
        sx={{ mb: 2 }} />
      <Tabs value={tab} onChange={(e, v) => setTab(v)} sx={{ mb: 2 }}>
        <Tab label={t('search.employees_tab')} />
        <Tab label={t('search.documents_tab')} />
      </Tabs>
      <Paper sx={{ p: 2 }}>
        {isLoading ? <CircularProgress /> : !debouncedQuery ? <Typography color="textSecondary">{t('search.type_query')}</Typography> : (
          <List>
            {(tab === 0 ? data?.employees : data?.documents)?.map((item, i) => (
              <ListItem key={i}>
                <ListItemText
                  primary={item.full_name || item.title || item.employee_name}
                  secondary={tab === 0 ? `${item.department_name || ''} - ${item.employee_id}` : item.document_type_name || ''}
                />
                <Chip label={tab === 0 ? item.status_display : item.file_extension} size="small" />
              </ListItem>
            )) || <Typography color="textSecondary">{t('search.no_results')}</Typography>}
          </List>
        )}
      </Paper>
    </Box>
  );
};

export default AdvancedSearchPage;
